{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if set(("nodes", "core_distance", "distances")) - set(case):
        raise ValueError("missing required field")

    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not all(isinstance(node, str) for node in nodes) or len(set(nodes)) != len(nodes):
        raise ValueError("nodes must be unique strings")
    if not isinstance(core, dict) or set(core) != set(nodes):
        raise ValueError("core_distance must contain exactly the nodes")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    def valid_weight(value):
        return (isinstance(value, (int, float)) and not isinstance(value, bool)
                and math.isfinite(value) and value >= 0)

    for node in nodes:
        if not valid_weight(core[node]):
            raise ValueError("invalid core distance")

    expected_count = len(nodes) * (len(nodes) - 1) // 2
    if len(distances) != expected_count:
        raise ValueError("distances must define every undirected pair")

    seen = set()
    edges = []
    node_set = set(nodes)
    for position, entry in enumerate(distances):
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("each distance entry must have three values")
        left, right, distance = entry
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("invalid distance endpoint")
        if not valid_weight(distance):
            raise ValueError("invalid distance")
        if right < left:
            left, right = right, left
        pair = (left, right)
        if pair in seen:
            raise ValueError("duplicate undirected distance")
        seen.add(pair)
        weight = max(core[left], core[right], distance)
        edges.append((weight, left, right, position))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    selected = []
    total_weight = 0
    for weight, left, right, _position in edges:
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            continue
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        selected.append({"left": left, "right": right, "weight": weight})
        total_weight += weight
        if len(selected) == len(nodes) - 1:
            break

    if len(selected) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    return {"mst_edges": selected, "total_weight": total_weight}
